{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "ocsync",
  "version": "0.1.0",
  "description": "Git-backed session sync for OpenCode V2",
  "type": "module",
  "license": "MIT",
  "author": "alv67",
  "homepage": "https://github.com/alv67/ocsync",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alv67/ocsync.git"
  },
  "bugs": {
    "url": "https://github.com/alv67/ocsync/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "session-sync",
    "git",
    "sync"
